import { requireText } from '../identity/identity-record.mjs';
export function normalizeLiveMessage(input) { const text = requireText(input?.text, 'liveMessage.text'); if (text.length > 2000) throw new TypeError('Live message exceeds 2000 characters'); return Object.freeze({ messageId: requireText(input?.messageId, 'messageId'), sessionId: requireText(input?.sessionId, 'sessionId'), parentMessageId: input?.parentMessageId || null, authorAccountId: requireText(input?.authorAccountId, 'authorAccountId'), actualAuthorActorId: requireText(input?.actualAuthorActorId, 'actualAuthorActorId'), actualAuthorInstanceId: requireText(input?.actualAuthorInstanceId, 'actualAuthorInstanceId'), deviceId: requireText(input?.deviceId, 'deviceId'), text, storyTimeRef: Object.freeze(structuredClone(input?.storyTimeRef)), observerAccountIds: Object.freeze([...new Set((input?.observerAccountIds || []).map(String))].sort()), aiJobId: input?.aiJobId || null }); }
export const liveMessageHeadId = (scope, messageId) => `live-message:${scope.storyId}:${scope.branchId}:${messageId}`;
